// Общие шаги для Admin Panel → Coupons (#351eb3, #a10206, #b93722) и блока Coupon в Billing. ТОЛЬКО ЧТЕНИЕ формы: Save не нажимается, купоны не создаются/не меняются
// (купоны нельзя удалить, они живые в Stripe). Страховка: любой запрос на создание/изменение купона обрывается и запоминается.
// Не сверено с сайтом при записи (правило проекта — не открывать сайт): подписи полей (по скриншотам 351eb3-*.png),
// способ сохранения (функция billing-perks и/или rest/v1 с «coupon») — перехват по признакам записи.
import { expect, Locator, Page } from '@playwright/test';
import { openPlansTabNamed } from '../admin-plans/plans-read-helpers';

export { startInTest, restoreTest } from '../multi-business/business-helpers';

export const LIMIT_ERROR_EN = 'At least 1, or leave it empty for no limit.';
export const LIMIT_ERROR_HE = 'לפחות 1, או להשאיר ריק ללא הגבלה.';
/** Купон без лимита, сохранённый на ручной проверке 18.10 (Disabled, привязан к wojeg27104). */
export const UNLIMITED_COUPON = 'QA-LNO-351-1810';
/** Купон с лимитом 3 (там же). */
export const LIMIT3_COUPON = 'QA-L1-351-1810';

/** Слова в имени rpc / action функции, означающие чтение (проверяются раньше слов записи). */
const READ_WORDS = /(list|get|check|validate|preview|quote|lookup|search)/i;
/** Слова, означающие запись купона/погашения или переход к оплате. */
const WRITE_WORDS = /(create|insert|update|save|upsert|delete|disable|enable|set|add|remove|redeem|apply|retry|sync|assign|checkout)/i;

/**
 * Страховка от записи: запросы, похожие на сохранение/отключение купона, погашение или создание Checkout-сессии, обрываются;
 * переход на checkout.stripe.com обрывается. Список — для expectNoCouponWrites.
 * Чтение пропускается: GET, rpc с «list/get/check/validate/preview…» в имени (admin_list_coupons, проверка кода в Billing).
 * // не сверено с сайтом: имя rpc/функции проверки кода в Billing — если Check оборвётся, тест упадёт явно (запись в hits).
 */
export async function blockCouponWrites(page: Page): Promise<string[]> {
  const hits: string[] = [];
  await page.route(/checkout\.stripe\.com/i, async (route) => {
    hits.push(`STRIPE ${route.request().url().slice(0, 120)}`);
    await route.abort();
  });
  await page.route(/billing-perks|coupon|checkout|\/functions\/v1\/[^?]*(billing|stripe)/i, async (route) => {
    const req = route.request();
    const method = req.method();
    if (method === 'GET' || method === 'OPTIONS' || method === 'HEAD') return route.continue();
    const url = req.url();
    const body = req.postData() ?? '';
    let isWrite: boolean;
    const rpc = url.match(/\/rest\/v1\/rpc\/([^?/]+)/i);
    if (rpc) {
      isWrite = !READ_WORDS.test(rpc[1]) && WRITE_WORDS.test(rpc[1]);
    } else if (/\/rest\/v1\//.test(url)) {
      isWrite = true; // прямой POST/PATCH/DELETE в таблицу купонов
    } else {
      const action = body.match(/"(action|op|type|mode)"\s*:\s*"([^"]*)"/i)?.[2] ?? '';
      isWrite = (!!action && !READ_WORDS.test(action) && WRITE_WORDS.test(action))
        || (!action && /checkout/i.test(url));
    }
    if (/max_redemptions/.test(body)) isWrite = true;
    if (isWrite) {
      hits.push(`${method} ${url} ${body.slice(0, 200)}`);
      return route.abort();
    }
    return route.continue();
  });
  return hits;
}

export function expectNoCouponWrites(hits: string[]) {
  expect(hits, 'тест не должен сохранять купоны').toEqual([]);
}

/** /adminpanel → вкладка Coupons, список загружен (есть колонка Used). */
