/** Поле поиска «Search by code or e-mail…». */
export function couponSearch(page: Page): Locator {
  return page.getByPlaceholder(/Search by code or e-mail/i).or(page.getByRole('searchbox')).first();
}

/** Фильтр состояния («All states»). // не сверено: нативный select или кастомный combobox — поддержаны оба. */
export function stateFilter(page: Page): Locator {
  return page.getByRole('combobox').filter({ hasText: /All states|Active|Disabled|Expired|Used up|Not in Stripe/ })
    .or(page.getByRole('combobox')).first();
}

export async function selectState(page: Page, label: string) {
  const control = stateFilter(page);
  const tag = await control.evaluate((el) => el.tagName.toLowerCase());
  if (tag === 'select') await control.selectOption({ label });
  else {
    await control.click();
    await page.getByRole('option', { name: label, exact: true }).click();
  }
}

/** Строки купонов (у заголовка и пустого состояния нет кнопки Redemptions). */
export function couponRows(page: Page): Locator {
  return page.locator('tr, [role="row"]').filter({ has: page.getByRole('button', { name: 'Redemptions', exact: true }) });
}

/** Тексты колонки по заголовку во всех строках купонов. */
export async function couponColumn(page: Page, header: string): Promise<string[]> {
  const headers = page.locator('th, [role="columnheader"]');
  await expect(headers.filter({ hasText: header }).first()).toBeVisible();
  const idx = (await headers.allInnerTexts()).map((t) => t.trim()).indexOf(header);
  expect(idx, `колонка «${header}»`).toBeGreaterThanOrEqual(0);
  const rows = couponRows(page);
  const n = await rows.count();
  const out: string[] = [];
  for (let i = 0; i < n; i++) out.push((await rows.nth(i).locator('td, [role="cell"]').nth(idx).innerText()).trim());
  return out;
}

/** После поиска/фильтра: либо «No coupons match these filters.» без строк, либо все строки удовлетворяют check. */
export async function expectRowsOrEmpty(page: Page, check: (rowText: string) => boolean, what: string, allowEmpty = true) {
  await expect(async () => {
    const rows = couponRows(page);
    if (allowEmpty && await page.getByText(NO_MATCH_EN, { exact: true }).isVisible()) {
      expect(await rows.count()).toBe(0);
      return;
    }
    const texts = await rows.allInnerTexts();
    expect(texts.length, `есть строки (${what})`).toBeGreaterThan(0);
    expect(texts.filter((t) => !check(t)), what).toEqual([]);
  }).toPass({ timeout: 15_000 });
}

/** Сегодня / вчера в часовом поясе браузера, формат YYYY-MM-DD (как value у input[type=date]). */
export async function browserDate(page: Page, offsetDays: number): Promise<string> {
  return page.evaluate((off) => {
    const d = new Date();
    d.setDate(d.getDate() + off);
    const p = (n: number) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
  }, offsetDays);
}

/** Пользователь (не админ): только язык EN, бизнес не трогаем. */
export async function startUserEn(page: Page) {
  await page.addInitScript(() => {
    try { window.localStorage.setItem('preferred-language', 'en'); } catch { /* ignore */ }
  });
}

/** Billing & Subscription → блок Coupon: поле кода и кнопка Check. */
export async function openBillingCoupon(page: Page) {
  await page.goto('/BillingSubscription');
  await expect(page.getByText('Coupons & referrals', { exact: true })).toBeVisible({ timeout: 30_000 });
  const check = page.getByRole('button', { name: 'Check', exact: true });
  await expect(check).toBeVisible();
  // не сверено: поле кода — ближайший input перед кнопкой Check (на скрине стоят в одну строку)
  const input = check.locator('xpath=preceding::input[1]');
  return { input, check };
}

/** Ввести код и нажать Check. */
export async function checkCoupon(page: Page, code: string) {
  const { input, check } = await openBillingCoupon(page);
  await input.fill(code);
  await check.click();
}
